-- MAYSTROON foundation. Private schema must NOT be exposed through PostgREST.
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.roles(id uuid primary key default gen_random_uuid(),name text not null unique check(name in ('OWNER','ADMIN','EDITOR','AUTHOR')));
create table if not exists public.user_roles(user_id uuid references auth.users(id) on delete cascade,role_id uuid references public.roles(id) on delete restrict,primary key(user_id,role_id));
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique check(slug ~ '^[a-z0-9-]+$'),description text,sort_order int not null default 0,is_active boolean not null default true,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.authors(id uuid primary key default gen_random_uuid(),profile_id uuid unique references public.profiles(id) on delete set null,display_name text not null,slug text not null unique,bio text,is_active boolean not null default true,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),title text not null check(length(title) between 1 and 300),slug text not null unique check(length(slug) between 1 and 200 and slug !~ '[/?#[:space:]]'),excerpt text,content text not null default '',cover_image text,author_id uuid references public.authors(id) on delete restrict,status text not null default 'draft' check(status in ('draft','review','scheduled','published','archived')),visibility text not null default 'public' check(visibility in ('public','private')),featured boolean not null default false,published_at timestamptz,scheduled_at timestamptz,seo_title text,seo_description text,reading_minutes int not null default 1 check(reading_minutes>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,check(status<>'published' or published_at is not null),check(status<>'scheduled' or scheduled_at is not null));
create table if not exists public.post_categories(post_id uuid references public.posts(id) on delete cascade,category_id uuid references public.categories(id) on delete restrict,primary key(post_id,category_id));
create table if not exists public.post_revisions(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,editor_id uuid references auth.users(id) on delete set null,snapshot jsonb not null,created_at timestamptz not null default now());
create table if not exists public.media_assets(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete set null,path text not null unique,mime_type text not null check(mime_type in ('image/jpeg','image/png','image/webp','image/avif')),size_bytes bigint not null check(size_bytes between 1 and 5242880),alt_text text,created_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,body text not null check(length(body) between 1 and 5000),status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists public.post_views(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,visitor_hash text not null,viewed_on date not null default current_date,created_at timestamptz not null default now(),unique(post_id,visitor_hash,viewed_on));
create table if not exists public.site_settings(key text primary key,value jsonb not null,is_public boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.ticker_items(id uuid primary key default gen_random_uuid(),text text not null check(length(text) between 1 and 500),url text check(url is null or url ~ '^https://' or url ~ '^/[^/]'),is_active boolean not null default false,sort_order int not null default 0,starts_at timestamptz not null default now(),ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or ends_at>starts_at));
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id text,created_at timestamptz not null default now());
create table if not exists private.owner_bootstrap(singleton boolean primary key default true check(singleton),completed_at timestamptz,user_id uuid references auth.users(id));
insert into private.owner_bootstrap(singleton) values(true) on conflict do nothing;
create table if not exists private.account_pins(user_id uuid primary key references auth.users(id) on delete cascade,pin_hash text not null,updated_at timestamptz not null default now());
create table if not exists private.rate_limits(key text primary key,hits int not null,expires_at timestamptz not null);
alter table private.owner_bootstrap enable row level security;
alter table private.account_pins enable row level security;
alter table private.rate_limits enable row level security;
create index if not exists posts_published_idx on public.posts(published_at desc,id) where status='published' and visibility='public' and deleted_at is null;
create index if not exists posts_author_idx on public.posts(author_id);
create index if not exists user_roles_role_idx on public.user_roles(role_id);
create index if not exists post_categories_category_idx on public.post_categories(category_id,post_id);
create index if not exists revisions_post_idx on public.post_revisions(post_id,created_at desc);
create index if not exists revisions_editor_idx on public.post_revisions(editor_id);
create index if not exists media_owner_idx on public.media_assets(owner_id);
create index if not exists comments_post_idx on public.comments(post_id);
create index if not exists comments_user_idx on public.comments(user_id);
create index if not exists views_post_idx on public.post_views(post_id);
create index if not exists audit_actor_idx on public.audit_logs(actor_id);
create index if not exists categories_order_idx on public.categories(sort_order) where is_active and deleted_at is null;
create index if not exists rate_expiry_idx on private.rate_limits(expires_at);
-- Only own roles are readable; role assignment is operator-only in Stage 1.
alter table public.profiles enable row level security;
revoke all on public.profiles from anon, authenticated;
alter table public.roles enable row level security;
revoke all on public.roles from anon, authenticated;
alter table public.user_roles enable row level security;
revoke all on public.user_roles from anon, authenticated;
alter table public.categories enable row level security;
revoke all on public.categories from anon, authenticated;
alter table public.authors enable row level security;
revoke all on public.authors from anon, authenticated;
alter table public.posts enable row level security;
revoke all on public.posts from anon, authenticated;
alter table public.post_categories enable row level security;
revoke all on public.post_categories from anon, authenticated;
alter table public.post_revisions enable row level security;
revoke all on public.post_revisions from anon, authenticated;
alter table public.media_assets enable row level security;
revoke all on public.media_assets from anon, authenticated;
alter table public.comments enable row level security;
revoke all on public.comments from anon, authenticated;
alter table public.post_views enable row level security;
revoke all on public.post_views from anon, authenticated;
alter table public.site_settings enable row level security;
