grant select on public.roles, public.categories, public.authors, public.posts, public.post_categories, public.site_settings, public.ticker_items to anon, authenticated;
grant select on public.profiles, public.user_roles to authenticated;
drop policy if exists roles_read on public.roles;
create policy roles_read on public.roles for select to anon, authenticated using (true);
drop policy if exists own_profile on public.profiles;
create policy own_profile on public.profiles for select to authenticated using (id=(select auth.uid()));
drop policy if exists own_roles on public.user_roles;
create policy own_roles on public.user_roles for select to authenticated using (user_id=(select auth.uid()));
drop policy if exists public_categories on public.categories;
create policy public_categories on public.categories for select to anon, authenticated using (is_active and deleted_at is null);
drop policy if exists public_authors on public.authors;
create policy public_authors on public.authors for select to anon, authenticated using (is_active and deleted_at is null);
drop policy if exists public_posts on public.posts;
create policy public_posts on public.posts for select to anon, authenticated using (status='published' and visibility='public' and deleted_at is null and published_at<=now());
drop policy if exists public_links on public.post_categories;
create policy public_links on public.post_categories for select to anon, authenticated using (exists(select 1 from public.posts p where p.id=post_id) and exists(select 1 from public.categories c where c.id=category_id));
drop policy if exists public_settings on public.site_settings;
create policy public_settings on public.site_settings for select to anon, authenticated using (is_public);
drop policy if exists public_ticker on public.ticker_items;
create policy public_ticker on public.ticker_items for select to anon, authenticated using (is_active and starts_at<=now() and (ends_at is null or ends_at>now()));
-- Internal authorization lookup: no user-controlled metadata, never exposed as RPC.
create or replace function private.is_staff() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=auth.uid() and r.name in ('OWNER','ADMIN','EDITOR')) $$;
revoke all on function private.is_staff() from public,anon;
grant usage on schema private to authenticated;
grant execute on function private.is_staff() to authenticated;
grant select on public.categories to authenticated;
drop policy if exists staff_read on public.categories;
create policy staff_read on public.categories for select to authenticated using ((select private.is_staff()));
grant select on public.authors to authenticated;
drop policy if exists staff_read on public.authors;
create policy staff_read on public.authors for select to authenticated using ((select private.is_staff()));
