-- No client mutations yet. Stage 2 will add narrowly scoped editorial policies.
grant all on all tables in schema public to service_role;
create or replace function public.consume_rate_limit(p_key text,p_limit int,p_seconds int) returns boolean language plpgsql security definer set search_path='' as $$
declare count_hits int;
begin
 if p_limit<1 or p_limit>1000 or p_seconds<1 or p_seconds>86400 or length(p_key)<>64 then raise exception 'invalid limit'; end if;
 delete from private.rate_limits where expires_at<now()-interval '1 day';
 insert into private.rate_limits(key,hits,expires_at) values(p_key,1,now()+make_interval(secs=>p_seconds)) on conflict(key) do update set hits=case when private.rate_limits.expires_at<=now() then 1 else private.rate_limits.hits+1 end,expires_at=case when private.rate_limits.expires_at<=now() then now()+make_interval(secs=>p_seconds) else private.rate_limits.expires_at end returning hits into count_hits;
 return count_hits<=p_limit;
end $$;
revoke all on function public.consume_rate_limit(text,int,int) from public,anon,authenticated;
grant execute on function public.consume_rate_limit(text,int,int) to service_role;
create or replace function public.set_account_pin(p_user_id uuid,p_hash text) returns void language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from auth.users u join public.user_roles ur on ur.user_id=u.id where u.id=p_user_id and u.email_confirmed_at is not null) then raise exception 'unauthorized'; end if;
 if p_hash !~ '^scrypt-v1\$[a-f0-9]{32}\$[a-f0-9]{128}$' then raise exception 'invalid hash'; end if;
 insert into private.account_pins(user_id,pin_hash) values(p_user_id,p_hash) on conflict(user_id) do update set pin_hash=excluded.pin_hash,updated_at=now();
 insert into public.audit_logs(actor_id,action,entity_type,entity_id) values(p_user_id,'pin_updated','account',p_user_id::text);
end $$;
revoke all on function public.set_account_pin(uuid,text) from public,anon,authenticated;
grant execute on function public.set_account_pin(uuid,text) to service_role;
-- Operator-only bootstrap: explicit verified UUID, transaction lock, permanently closes.
create or replace function private.bootstrap_owner(p_user_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare target_email text; confirmed timestamptz;
begin
 perform 1 from private.owner_bootstrap where singleton=true for update;
 if exists(select 1 from private.owner_bootstrap where completed_at is not null) then raise exception 'bootstrap closed'; end if;
 select email,email_confirmed_at into target_email,confirmed from auth.users where id=p_user_id;
 if target_email is distinct from 'mtzallqmy@gmail.com' or confirmed is null then raise exception 'verified owner identity required'; end if;
 if exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where r.name='OWNER') then raise exception 'owner already exists'; end if;
 insert into public.profiles(id,display_name) values(p_user_id,'معتز العلقمي') on conflict(id) do nothing;
 insert into public.user_roles(user_id,role_id) select p_user_id,id from public.roles where name='OWNER';
 update private.owner_bootstrap set completed_at=now(),user_id=p_user_id where singleton=true;
 insert into public.audit_logs(actor_id,action,entity_type,entity_id) values(p_user_id,'owner_bootstrap','account',p_user_id::text);
end $$;
revoke all on function private.bootstrap_owner(uuid) from public,anon,authenticated,service_role;
create or replace function private.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end $$;
revoke all on function private.touch_updated_at() from public,anon,authenticated;
drop trigger if exists touch_updated_at on public.profiles;
create trigger touch_updated_at before update on public.profiles for each row execute function private.touch_updated_at();
drop trigger if exists touch_updated_at on public.categories;
create trigger touch_updated_at before update on public.categories for each row execute function private.touch_updated_at();
drop trigger if exists touch_updated_at on public.authors;
