create or replace function private.estimate_reading_time() returns trigger language plpgsql set search_path='' as $$ begin new.reading_minutes=greatest(1,ceil(array_length(regexp_split_to_array(trim(new.content),'\s+'),1)::numeric/200)::int);return new;end $$;
revoke all on function private.estimate_reading_time() from public,anon,authenticated;
drop trigger if exists estimate_reading_time on public.posts;
create trigger estimate_reading_time before insert or update of content on public.posts for each row execute function private.estimate_reading_time();
